nodes.func:
msg.payload = { status: 'success', job: 'maintain_iotawatt_archive', completed_at: new Date().toISOString() };
node.status({fill:'green',shape:'dot',text:'archive succeeded'});
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const row = rows[0] || {};
const ageHours = Number(row.AgeHours);
const stale = !row.LastArchiveSuccessUTC || !Number.isFinite(ageHours) || ageHours > 36;

if (!stale) {
    node.status({fill:'green',shape:'dot',text:`healthy: ${ageHours}h`});
    msg.payload = { status: 'healthy', age_hours: ageHours, last_success_utc: row.LastArchiveSuccessUTC };
    return [null, msg];
}

node.status({fill:'red',shape:'ring',text:'archive stale'});
const now = Date.now();
const lastAlert = flow.get('iotawattArchiveLastStaleAlert') || 0;
if (now - lastAlert < 12 * 60 * 60 * 1000) return [null, null];
flow.set('iotawattArchiveLastStaleAlert', now);
msg.title = 'IotaWatt archive is stale';
msg.payload = `No successful IotaWatt hourly archive has been recorded within 36 hours. Last success UTC: ${row.LastArchiveSuccessUTC || 'never'}. Age hours: ${Number.isFinite(ageHours) ? ageHours : 'unknown'}. Pruning remains locked.`;
msg.device = global.get('BradPhoneNM') || 'pixel8';
return [msg, null];

const detail = (msg.error && msg.error.message) ? msg.error.message : String(msg.payload || 'unknown database error');
const now = Date.now();
const lastAlert = flow.get('iotawattArchiveLastErrorAlert') || 0;
if (now - lastAlert < 30 * 60 * 1000) return null;
flow.set('iotawattArchiveLastErrorAlert', now);
msg.title = 'IotaWatt archive failure';
msg.payload = `IotaWatt archive/watchdog database error: ${detail}. Pruning remains locked.`;
msg.device = global.get('BradPhoneNM') || 'pixel8';
return msg;
